  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://acure.com/pages/ambassadors-program-terms-conditions', 'official_site', 'affiliate', 'ACURE''s official Ambassadors Program terms (effective August 15, 2026) state Ambassadors earn 25% commission on qualifying purchases by new customers and 10% on purchases by returning customers, calculated on the order subtotal after discounts, paid through Shopify Collabs, with a 15% community discount code. No cap on earnings is stated anywhere in the terms, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://acure.com/pages/ambassadors-program-terms-conditions', 'official_site', 'contact', 'The same official terms publish partnerships@acure.com as the contact for program questions and support, and set eligibility at 18+, resident in the contiguous United States, accepted through the program''s application and approval process.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://acure.com/pages/ambassadors-program-terms-conditions', 'official_site', 'ugc_collab', 'The terms are written for creators: Ambassadors are expected to create honest content about ACURE products, and ACURE takes a license to repost and feature Ambassador content across its digital and marketing channels — a structured creator program rather than a plain publisher link scheme.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 18, 13, 8, 4, '{"compensation": "25% on new-customer purchases (10% on returning) published in the brand''s own program terms \u2014 among the highest verified rates in this round; no cap statement is published, so the cap stays unknown.", "contact_access": "A published program contact email (partnerships@acure.com) in the official terms plus a defined application route \u2014 top band per the rubric.", "credibility": "Established clean-beauty brand with a formal, dated terms document for its creator program and national brand recognition.", "niche_fit": "Skincare-led clean beauty with hair and body lines \u2014 squarely in the beauty/skincare UGC niche.", "opportunity_availability": "Applications are open via Shopify Collabs with an approval step; eligibility is limited to contiguous-US residents 18+.", "ugc_evidence": "A creator-specific Ambassador program on Shopify Collabs with content expectations, content-usage licensing and community discount codes written into its terms."}'::jsonb);
