  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/89089', 'official_site', 'affiliate', 'Keranique''s official Awin merchant profile advertises ''Up to 15% commission'', an active affiliate management team, and instructs influencers to use their social media handle on the ShareASale application in place of a website name — an explicitly influencer-welcoming program. No cap statement is published, so the cap is recorded as unknown.', 'verified', now());
