  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dreadfullhippie.com/pages/affiliate-program', 'official_site', 'affiliate', 'DreadFullHippie''s official affiliate page and program terms state affiliates earn 15% of the order subtotal on every order tracked to their link or code, with a 15-day tracking window, monthly PayPal payouts and a $5 minimum, run on GoAffPro. No cap on earnings is stated, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dreadfullhippie.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'The same page is built around creators: no follower minimum (''A small, engaged following often sells better than a big one''), every application reviewed by hand by the small Utah team, content guidance for install/transformation videos, a parallel TikTok Shop creator route with refundable samples, and product gifting for active affiliates — direct evidence of a small, early-stage creator base, so saturation is marked low.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dreadfullhippie.com/pages/affiliate-program', 'official_site', 'contact', 'The page publishes info@dreadfullhippie.com and a phone number (801-509-0428) for affiliate questions, stressing affiliates reach ''a real person on our team'', and cites 4.9 stars from more than 6,500 reviews.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 15, 13, 13, 9, 3, '{"compensation": "A published 15% rate on high-ticket orders ($500-$1,000+ complete looks) makes single sales meaningful; no cap statement is published.", "contact_access": "Published email and phone with a promise of a real person, plus a short application form \u2014 top band per the rubric.", "credibility": "Small handmade brand, but its own page cites 4.9 stars across 6,500+ reviews and full published program terms.", "niche_fit": "Dreadlock extensions are a narrow but highly visual hair niche; transformation content fits beauty UGC well, though the audience is specialised.", "opportunity_availability": "Open application now with no follower minimum and hand review \u2014 among the most accessible programs in this round.", "ugc_evidence": "A creator-first program: content playbooks, TikTok Shop integration, refundable filming samples and gifting for consistent creators."}'::jsonb);
