  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dermae.com/pages/guide-to-register-as-our-affiliate', 'official_site', 'affiliate', 'DERMA E''s official affiliate guide confirms the program is set up with the Rakuten Affiliate Network and walks publishers through registering, finding DERMA E in the advertiser search and applying, with approval taking a couple of days. The official page publishes no commission percentage, and directory figures conflict (Shopper reports 3.72-4.66%; a Lasso roundup claims up to 22.5%), so the rate is recorded as null rather than guessed. No cap statement is published.', 'verified', now());
