  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Alpyn Beauty Affiliate Program (ShareASale)', 'https://linkclicky.com/affiliate-program/alpyn-beauty/', 'https://linkclicky.com/affiliate-program/alpyn-beauty/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/alpyn-beauty/', 'listing', 'affiliate', 'LinkClicky''s program listing records Alpyn Beauty''s affiliate program as running on ShareASale at 10% per sale with a 30-day cookie, described as the rate officially listed with the program. Other roundups claim 20-25%, which could not be reconciled with the network listing, so the conservative 10% network figure is recorded and the conflict flagged. No cap statement is published anywhere fetched.', 'publicly_reported', now());
