  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fableandmane.com/pages/affiliates', 'official_site', 'affiliate', 'Fable & Mane''s official affiliates page invites creators to ''Join our program on Rakuten or LTK to start earning'', with exclusive affiliate links and perks including early access to new products, special offers and insider content. No commission percentage is published on the page or in any fetched source, so the rate is recorded as null; no cap statement is published either.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/fable-mane', 'listing', 'ugc_collab', 'NewCollab''s brand page reports Fable & Mane works with creators mainly through gifting (typical PR package ~$80 around the HoliRoots Hair Oil), looks for around 5K+ followers, and replies to pitches in about 5 days — creator collaboration is active but pitch-led rather than an open UGC program.', 'publicly_reported', now());
