  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 7, 7, 7, 4, '{"compensation": "No commission rate is published on the official page or any fetched source, so compensation scores low until confirmed inside Rakuten or LTK.", "contact_access": "An official affiliates page plus a collaboration request route, but no published partnerships email \u2014 mid-range per the rubric.", "credibility": "Premium Ayurvedic haircare brand founded in 2020 with major beauty-retail presence.", "niche_fit": "Ayurvedic hair oils and scalp rituals are a distinctive, content-friendly haircare niche.", "opportunity_availability": "Joining is open via Rakuten or LTK today, though terms are only visible inside those platforms.", "ugc_evidence": "Affiliate routes plus an active gifting/PR creator pipeline (5K+ follower guidance on NewCollab) show real creator collaboration, if pitch-led."}'::jsonb);
