  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/herbivore-botanicals/', 'listing', 'affiliate', 'LinkClicky''s listing records Herbivore Botanicals'' affiliate program on the Impact platform at 4% per sale, while Shopper reports up to 12% — the figures conflict and neither comes from the brand''s own page, so the rate is recorded as null rather than picking one. No cap statement is published anywhere fetched.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/herbivore-botanicals', 'listing', 'ugc_collab', 'NewCollab''s brand page reports Herbivore Botanicals actively gifts creators (typical PR package ~$50), looks for around 500+ followers with niche fit mattering more than size, works with creators worldwide, and routes applications through a direct form — evidence of an accessible creator pipeline, though not a creator count, so saturation stays unknown.', 'publicly_reported', now());
