  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 6, 6, 7, 4, '{"compensation": "No rate could be verified from the brand itself and directory figures conflict (4% vs up to 12%), so the rate is null and compensation scores lowest in this round.", "contact_access": "A direct creator application route via NewCollab, but no published partnerships email was verified \u2014 lower band per the rubric.", "credibility": "Well-known plant-based skincare brand founded in 2011 with broad retail and press presence.", "niche_fit": "Plant-powered serums and moisturizers are a core skincare UGC niche.", "opportunity_availability": "Creator gifting applications are open with a low 500+ follower guideline; the Impact affiliate program is joinable through the network.", "ugc_evidence": "Active creator gifting with a direct application form and low follower threshold, plus a network affiliate program \u2014 real creator collaboration, if gifting-led."}'::jsonb);
