  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gym-pin.co.uk/pages/affiliate-programme-terms-and-conditions', 'official_site', 'affiliate', 'GymPin''s official Affiliate Programme Terms (Version 1.0, effective 19 August 2026) state affiliates earn 10% commission on Net Qualifying Sales, the audience gets 10% off, tracking lasts up to 30 days, and state verbatim: ''commission is uncapped''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gym-pin.co.uk/blogs/articles/why-become-a-gympin-affiliate', 'official_site', 'affiliate', 'GymPin''s official programme overview repeats the offer as ''10% commission on qualifying referred sales, with no earnings cap'', a 10% audience discount and a 30-day tracking window, with Bronze/Silver/Gold progression.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gym-pin.co.uk/pages/the-gympin-affiliate-programe', 'official_site', 'ugc_collab', 'The programme page (''Create content. Build trust. Earn 10%.'') is built for content creators, applications are reviewed manually by the GymPin team (''Acceptance is not automatic''), and the terms are Version 1.0 effective August 2026 — a newly launched, small programme, which is the basis for the low-saturation mark.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 15, 9, 8, 3, '{"compensation": "Published 10% commission with an explicit uncapped statement in the brand''s own terms, plus a 10% audience discount.", "contact_access": "A public application page with manual team review, but no published partnerships email.", "credibility": "A small UK specialist (GYMPIN (UK) LTD, registered in England and Wales) with a narrow product range and little independent coverage.", "niche_fit": "Strength-training equipment and cable attachments are a core fitness-creator niche, though narrower than apparel.", "opportunity_availability": "Applications are open now at the Bronze entry level, subject to manual approval.", "ugc_evidence": "A dedicated Athlete Programme with creator-facing content licensing terms and tier progression, but at a very early stage."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Gymreapers', 'https://www.gymreapers.com', 'Performance fitness brand for serious lifters selling lifting belts, knee sleeves, wrist wraps, straps and training apparel, known for a large multi-program creator operation spanning sponsored athletes, commission-only affiliates, TikTok creators and brand ambassadors.', null, 'published') returning id into bid;
