  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.socialsnowball.io/post/gymreapers-affiliate-marketing-case-study.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.socialsnowball.io/post/gymreapers-affiliate-marketing-case-study', 'listing', 'affiliate', 'Social Snowball''s case study of Gymreapers'' program publishes its tier structure: Tier 1 Elite Sponsored Athletes, Tier 2 Growth Athletes and Tier 3 Proven Performers each earn retainers plus 10% commission, and Tier 4 Community/Affiliate Base is commission-only at 10% with a welcome gift — the open entry point for UGC creators.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.socialsnowball.io/post/gymreapers-affiliate-marketing-case-study', 'listing', 'ugc_collab', 'The same case study says Gymreapers runs separate programs for athletes, commission-only affiliates, TikTok creators and ambassadors (including a dedicated TikTok Shop affiliate program), with affiliates driving 10% of total revenue ($85K-$100K per month) — a large, mature creator operation, so no low-saturation claim is made.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 13, 7, 7, 4, '{"compensation": "10% commission at every tier per the published case study, with retainers at upper tiers; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No published partnerships email or official application page was verified in the fetched sources.", "credibility": "Established lifting brand whose affiliate channel alone is reported at $85K-$100K revenue per month.", "niche_fit": "Lifting gear and apparel built for gym creators \u2014 squarely in the fitness UGC niche.", "opportunity_availability": "The Tier 4 community/affiliate base is the open entry point, but joining routes run through the brand''s program pages rather than a public network listing.", "ugc_evidence": "A documented multi-program creator strategy with a dedicated TikTok affiliate program and a commission-only UGC entry tier."}'::jsonb);
