  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 6, 10, 7, 4, '{"compensation": "No commission rate is published anywhere fetched, so this stays low per the rubric despite the program being live.", "contact_access": "A dedicated official collabs page with both an affiliate join route and a creator application \u2014 good access, though no published email.", "credibility": "Established direct-to-consumer travel gear brand with a long-running flagship backpack line.", "niche_fit": "Camera and travel bags are a staple of travel/photography creator content \u2014 strong niche fit.", "opportunity_availability": "Affiliate sign-up is open via Awin; creator campaign applications are only reviewed quarterly.", "ugc_evidence": "Two structured routes on the brand''s own site: an Awin affiliate program plus a Creator Community for product campaigns."}'::jsonb);
