  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/organifi/', 'listing', 'affiliate', 'Lasso''s Organifi program listing states a 20% per-sale commission for affiliates promoting its superfood supplements, with applications reviewed over a few days. Other directories report different figures (5% base via FlexOffers, 20-30% via Affiliate Explorer), so the rate should be re-confirmed at sign-up; no fetched source states any cap on earnings, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/organifi-affiliate-program-in-depth-review-pros-and-cons', 'listing', 'general', 'Creator Hero''s review describes Organifi, established in 2014, as a superfood supplement brand whose affiliate partners get product samples, exclusive promotions and a dedicated account manager, with a base rate of 5% rising to 20% for premium content sites via FlexOffers.', 'publicly_reported', now());
