  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 16, 8, 8, 4, '{"compensation": "Lasso lists 20% per sale, among the higher published rates in the supplement niche, though directories disagree (5% base to 30% reported), so the figure needs re-confirming at sign-up.", "contact_access": "Joinable through FlexOffers and Refersion with an application review, but no published partnerships email was found on a fetched page.", "credibility": "Operating since 2014 with a large catalog and an affiliate program covered by multiple independent directories.", "niche_fit": "Superfood powders and daily wellness supplements are core health-creator content, easy to build routines around.", "opportunity_availability": "Applications are open now through public network listings with approval typically within about a week.", "ugc_evidence": "A long-running affiliate/ambassador program with samples, exclusive promotions and a dedicated account manager for partners."}'::jsonb);
