  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.onnit.com/affiliate-program', 'official_site', 'affiliate', 'Onnit''s official affiliate page states the program runs on Impact, applications are reviewed within 72 hours, and ''we have a very limited number of spots available for program acceptance'' — direct evidence the creator pool is deliberately kept small.', 'verified', now());
