  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 14, 9, 6, 5, '{"compensation": "Most detailed listings report 15% on regular products plus a $10 bounty on trial products via Impact, though some directories list 10-12%, so confirm in the marketplace.", "contact_access": "A dedicated official program page with an application and a named program manager follow-up, but no published email.", "credibility": "Major performance brand owned by Unilever since 2021, with celebrity and pro-athlete endorsements.", "niche_fit": "Nootropics, supplements and functional training gear sit squarely in the health and biohacking creator niche.", "opportunity_availability": "Applications are open, but the brand states spots are very limited and reviewers look for an established platform.", "ugc_evidence": "A structured Impact program built around creators and endorsers, with application review inside 72 hours per the official page."}'::jsonb);
