  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/burrow', 'listing', 'affiliate', 'Affi.io''s reproduction of Burrow''s own program text: ''Our Affiliate Program is designed to reward creators, influencers, and publishers who share our passion for modern, functional, and sustainable home design… earn competitive commissions''; direct linking and email marketing supported, incentivized partners reviewed case-by-case, no trademark bidding.', 'publicly_reported', now());
